import { branchById } from '../config/branches.js';
import { composeNotice } from '../notices/compose.js';
import { pickupDeadline } from './pickup-shelf.js';

/** Returns the notice that tells a member their hold is ready to collect. */
export function holdReadyNotice(store, hold) {
  const member = store.getMember(hold.memberId);
  const item = store.getItem(hold.itemId);
  return composeNotice('holdReady', {
    member,
    values: {
      title: item.title,
      branch: branchById(hold.pickupBranchId).name,
      deadline: pickupDeadline(hold),
    },
  });
}
import { branchById } from '../config/branches.js';
import { addDays, nextOpenDay } from '../helpers/dates.js';

/** How many days a ready hold waits on the pickup shelf. */
export const PICKUP_DAYS = 10;

/** Returns the last day a ready hold can be collected at its pickup branch. */
export function pickupDeadline(hold) {
  return nextOpenDay(branchById(hold.pickupBranchId), addDays(hold.readyOn, PICKUP_DAYS));
}

/** Marks every ready hold whose pickup deadline has passed by `today` as expired, and returns them. */
export function expireUncollectedHolds(store, today) {
  const expired = [];
  for (const hold of store.listAllHolds()) {
    if (hold.status === 'ready' && pickupDeadline(hold) < today) {
      expired.push(store.saveHold({ ...hold, status: 'expired' }));
    }
  }
  return expired;
}
/** Puts a member in the queue for an item. Returns { ok: true, hold } or { ok: false, reason }. */
export function placeHold(store, { itemId, memberId, pickupBranchId, today }) {
  if (store.getItem(itemId) === undefined) return { ok: false, reason: 'unknown-item' };
  if (holdQueue(store, itemId).some((hold) => hold.memberId === memberId)) {
    return { ok: false, reason: 'already-queued' };
  }
  const hold = store.saveHold({
    itemId,
    memberId,
    pickupBranchId,
    placedOn: today,
    status: 'waiting',
    readyOn: null,
  });
  return { ok: true, hold };
}

/** Returns the holds still waiting or ready for an item, the first placed first. */
export function holdQueue(store, itemId) {
  return store
    .listHolds(itemId)
    .filter((hold) => hold.status === 'waiting' || hold.status === 'ready')
    .sort(
      (first, second) => first.placedOn.localeCompare(second.placedOn) || first.id.localeCompare(second.id),
    );
}

/**
 * Makes the first waiting hold for an item ready for pickup from today, and returns it; returns
 * null when nobody is waiting.
 */
export function fulfilNextHold(store, itemId, today) {
  const next = holdQueue(store, itemId).find((hold) => hold.status === 'waiting');
  if (next === undefined) return null;
  return store.saveHold({ ...next, status: 'ready', readyOn: today });
}
import { normaliseBarcode } from '../catalog/barcodes.js';
import { assessLateFee } from '../fees/assess.js';
import { holdReadyNotice } from '../holds/notify.js';
import { fulfilNextHold } from '../holds/queue.js';

/**
 * Takes an item back: closes its loan, charges any late fee and readies the next hold for it.
 * Returns { ok: true, loan, feeCents, notice } or { ok: false, reason }; notice is null when
 * nobody was waiting for the item.
 */
export function returnItem(store, { barcode, today }) {
  const item = store.findItemByBarcode(normaliseBarcode(barcode));
  if (item === undefined) return { ok: false, reason: 'unknown-item' };
  const loan = store.findOpenLoan(item.id);
  if (loan === undefined) return { ok: false, reason: 'not-on-loan' };
  const closed = store.saveLoan({ ...loan, returnedOn: today });
  const member = store.getMember(loan.memberId);
  const feeCents = assessLateFee({ loan, item, member, returnedOn: today });
  if (feeCents > 0) {
    store.saveFee({
      memberId: member.id,
      loanId: loan.id,
      amountCents: feeCents,
      paid: false,
      waivedReason: null,
    });
  }
  const hold = fulfilNextHold(store, item.id, today);
  return { ok: true, loan: closed, feeCents, notice: hold === null ? null : holdReadyNotice(store, hold) };
}

